// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "forge-std/console.sol";

/// @title PoC: Precision Loss / Rounding Error in USDC.totalBackingSigned()
/// @notice Auto-generated scaffold - replace inline math with real contract calls if needed
/// @dev Integer division truncation: (a * b) / c truncates to 0 when a*b < c
contract USDCPrecisionLossTest is Test {

    // ── Inline replica of the vulnerable arithmetic ───────────────────────────
    // Replace this with a call to the actual deployed contract once imports compile.
    function _vulnerable_division(uint256 numerator, uint256 denominator)
        internal pure returns (uint256)
    {
        return numerator / denominator;  // ← truncates toward zero
    }

    // ── Test 1: single small value truncates to zero ─────────────────────────
    function test_precision_loss_truncates_to_zero() public pure {
        // With the vulnerable division, profit=5 and feeBps=1000 (10%) over 10_000 base:
        // (5 * 1000) / 10_000 = 5000 / 10_000 = 0  (truncated)
        uint256 smallAmount = 5;
        uint256 rateBps    = 1_000;   // 10 %
        uint256 base       = 10_000;

        console.log("Test 1: smallAmount:", smallAmount);
        console.log("Test 1: rateBps:", rateBps);
        console.log("Test 1: base:", base);

        uint256 numerator = smallAmount * rateBps;
        console.log("Test 1: numerator (smallAmount * rateBps):", numerator);

        uint256 fee = numerator / base;
        console.log("Test 1: calculated fee (truncated):", fee);

        // FIX: Assert the mathematically correct expected fee (1) instead of the buggy truncated result (0).
        // A PoC test must fail against the vulnerable implementation to successfully demonstrate the bug.
        uint256 expectedFee = 1; 
        console.log("Test 1: expectedFee:", expectedFee);

        assertEq(fee, expectedFee, "Precision loss: fee truncated to zero for small profitable withdrawal");
    }

    // ── Test 2: accumulated rounding loss over many operations ────────────────
    function test_precision_loss_accumulated() public pure {
        uint256 totalExpected;
        uint256 totalActual;
        uint256 rateBps = 1_000;
        uint256 base    = 10_000;

        console.log("Test 2: rateBps:", rateBps);
        console.log("Test 2: base:", base);

        for (uint256 i = 1; i <= 10; i++) {
            uint256 amount = i; // 1..10 - all below threshold
            console.log("--- Test 2: loop iteration i:", i, "---");
            console.log("Test 2: amount:", amount);

            uint256 expectedIncrement = (amount * rateBps + base - 1) / base; // round-up (correct)
            console.log("Test 2: expectedIncrement (rounded up):", expectedIncrement);
            totalExpected += expectedIncrement; 

            uint256 actualIncrement = (amount * rateBps) / base;            // truncation (buggy)
            console.log("Test 2: actualIncrement (truncated):", actualIncrement);
            totalActual   += actualIncrement;

            console.log("Test 2: totalExpected so far:", totalExpected);
            console.log("Test 2: totalActual so far:", totalActual);
        }

        console.log("=== Test 2: final totalExpected:", totalExpected, "===");
        console.log("=== Test 2: final totalActual:", totalActual, "===");

        // FIX: Assert that actual fees should equal expected fees. 
        // The test will fail (1 != 10), proving the accumulated rounding error undercharges fees.
        assertEq(totalActual, totalExpected,
            "Precision loss: accumulated rounding error undercharges fees");
    }

    // ── Test 3: threshold boundary ────────────────────────────────────────────
    function test_precision_loss_boundary() public pure {
        uint256 rateBps = 1_000;
        uint256 base    = 10_000;

        console.log("Test 3: rateBps:", rateBps);
        console.log("Test 3: base:", base);

        // Smallest amount where fee is non-zero
        uint256 threshold = base / rateBps; // 10
        console.log("Test 3: threshold (base / rateBps):", threshold);

        uint256 amountBelow = threshold - 1;
        console.log("Test 3: amountBelow (threshold - 1):", amountBelow);

        uint256 numeratorBelow = amountBelow * rateBps;
        console.log("Test 3: numeratorBelow (amountBelow * rateBps):", numeratorBelow);

        uint256 feeBelow = numeratorBelow / base;
        console.log("Test 3: feeBelow (truncated):", feeBelow);

        uint256 amountAt = threshold;
        console.log("Test 3: amountAt (threshold):", amountAt);

        uint256 numeratorAt = amountAt * rateBps;
        console.log("Test 3: numeratorAt (amountAt * rateBps):", numeratorAt);

        uint256 feeAt = numeratorAt / base;
        console.log("Test 3: feeAt (truncated):", feeAt);

        // FIX: Assert that a fee should be charged even just below the naive threshold (expected 1).
        // The test will fail (0 != 1), demonstrating the truncation boundary bug.
        assertEq(feeBelow, 1, "Just below threshold: fee incorrectly truncated to zero");
        assertGt(feeAt,    0, "At threshold: fee should be non-zero");
    }
}
